/* ------------------------------------------------------------ matching */
// keyOf, forms and distance live in match.js (shared with Reef Rush's prompt bank).
import { keyOf, forms, distance } from "./match.js";
export { keyOf };

export const CATEGORIES = {};
for (const [id, c] of Object.entries(RAW)) {
  const answers = []; // { show, keys }
  const exact = new Map(); // key -> answer index
  for (const item of c.list.split(",")) {
    const names = item.split("|").map((s) => s.trim()).filter(Boolean);
    if (!names.length) continue;
    const show = names[0];
    const keys = names.map(keyOf).filter(Boolean);
    // The same answer listed twice (it happens in long lists, sometimes once as a plural) is
    // kept once, so two players who typed "date" and "dates" gave the same answer.
    const dup = keys.find((k) => exact.has(k)) ?? keys.flatMap((k) => [...forms(k)]).find((f) => exact.has(f));
    const idx = dup !== undefined ? exact.get(dup) : answers.push({ show, keys: [] }) - 1;
    for (const k of keys) if (!exact.has(k)) (exact.set(k, idx), answers[idx].keys.push(k));
  }
  // Plural/singular forms of every name, unless that form is some other answer's own name.
  const loose = new Map();
  for (const [k, idx] of exact) for (const f of forms(k)) if (!exact.has(f) && !loose.has(f)) loose.set(f, idx);
  CATEGORIES[id] = { id, ask: c.ask, answers, exact, loose };
}

// Which answer in category id did they mean? Returns { id: answer index, show } or null.
export function match(id, text) {
  const cat = CATEGORIES[id];
  const k = keyOf(text);
  if (!cat || k.length < 2) return null;
  let idx = cat.exact.get(k) ?? cat.loose.get(k);
  if (idx === undefined) for (const f of forms(k)) if ((idx = cat.exact.get(f) ?? cat.loose.get(f)) !== undefined) break;
  // A small typo in a longer answer: one letter off (two in long ones).
  if (idx === undefined && k.length >= 5) {
    const limit = k.length >= 9 ? 2 : 1;
    let best = limit + 1;
    for (const [key, i] of cat.exact) {
      if (Math.abs(key.length - k.length) > limit || key.length < 4) continue;
      const d = distance(k, key, limit);
      if (d < best) (best = d), (idx = i);
    }
  }
  if (idx === undefined) return null;
  return { idx, show: cat.answers[idx].show };
}
